import base64, zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
stage1a = zlib.decompress(base64.b64decode("""""")).decode("utf-8")
shim = zlib.decompress(base64.b64decode("""""")).decode("utf-8")

(ROOT / "src/flow_stp/stage1/stage1a.py").write_text(stage1a, encoding="utf-8")
(ROOT / "src/flow_stp/stage1/_stage1a_model_impl.py").write_text(shim, encoding="utf-8")
print("Applied selected Stage 1a implementation.")
